"explanation": "CJD訴訟は、脳外科手術等で用いられたヒト乾燥硬膜を介してプリオン（タンパク質性の感染因子）に汚染された患者がクロイツフェルト・ヤコブ病を発症した薬害事件である(試験問題作成の手引き第1章)。\n\nA：CJDの原因はウイルスではなくプリオン（異常プリオンタンパク質）。抗ウイルス薬による予防はできない。\nB：HIV訴訟の説明であり、CJD訴訟は血液凝固因子製剤ではなくヒト乾燥硬膜が原因。\nC：抗生物質や細菌は無関係。\n\n【頻出】CJD＝プリオン＝ヒト乾燥硬膜の移植のセットで暗記。\n【関連】CJD訴訟もHIV訴訟と同様、生物由来製品による感染被害の救済制度（平成16年創設）の整備につながった。"
