"explanation": "機能性表示食品は、事業者の責任において、科学的根拠に基づき特定の保健の目的が期待できる旨を表示する食品で、消費者庁長官への届出制であり、医薬品ではない(食品表示法・試験問題作成の手引き第1章)。\n\nA：健康食品は医薬品ではなく、薬機法に基づく承認の対象外。特定保健用食品は消費者庁長官の許可制。\nB：特定保健用食品は「保健の用途」の表示はできるが、疾病の「治療」や「予防」の効能効果は表示できない（医薬品との区別）。\nD：健康食品でも医薬品との相互作用は起こり得る（例：セイヨウオトギリソウとワルファリン等）。\n\n【頻出】「トクホは個別許可制（消費者庁長官）」「機能性表示食品は届出制」の違いは頻出。\n【関連】健康食品は栄養機能食品（規格基準型）、特定保健用食品（個別許可型）、機能性表示食品（届出型）の3類型で整理する。"
