"answer": 1,
"explanation": "クロルフェニラミンマレイン酸塩・ケトチフェンフマル酸塩等の抗ヒスタミン成分は、目のアレルギー症状（かゆみ・充血・腫れ等）を緩和する目的で点眼薬に配合される(試験問題作成の手引き第3章)。\n\nA：ナファゾリン塩酸塩等の血管収縮成分は連用により薬剤性結膜炎・反跳性充血を生じることがあり、長期連用は適切でない。\nC：血管収縮成分は緑内障の症状を悪化させるおそれがあり、緑内障の人は使用を避けるか相談が必要。\nD：点眼薬の抗ヒスタミン成分は主に局所作用を目的とし、鼻炎症状の改善目的では用いられない。\n\n【頻出】「点眼薬の血管収縮成分は連用注意＋緑内障注意」「抗ヒスタミン成分はかゆみ・充血緩和」は必出。\n【関連】コンタクトレンズ装用中の使用は添付文書の指示に従う。ソフトコンタクトレンズは成分を吸着するため装用中の使用が制限されるものが多い。"
