"explanation": "医薬部外品は人体に対する作用が緩和なものとして定義されており、表示できる効能効果も特定のものに限定される（吐き気防止・口臭体臭防止・あせも防止・脱毛防止・育毛・除毛・衛生害虫防除等）(試験問題作成の手引き第4章、薬機法第2条第2項)。\n\nA：医薬部外品と医薬品では適用される規制が異なる。\nB：医薬部外品は医薬品より人体への作用が緩和。\nD：薬機法第59条により、医薬部外品の容器または被包には「医薬部外品」の文字を記載する義務がある。\n\n【頻出】「医薬部外品＝作用緩和＋効能効果限定」「医薬部外品の文字記載義務」は必出。\n【関連】医薬部外品の販売は医薬品販売業の許可は不要で、一般小売店でも販売できる。"
